import { integer, pgTable, text, timestamp, uuid } from "drizzle-orm/pg-core";

// Conventions (docs/decisions/0009): UUIDv7 ids generated by the client, UTC timestamps,
// soft delete via deleted_at. Same table and column names as the iOS SQLite schema.
const timestamps = {
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  deletedAt: timestamp("deleted_at", { withTimezone: true }),
};

// Root of all user data, so it has no athlete_id of its own.
export const athlete = pgTable("athlete", {
  id: uuid("id").primaryKey(),
  displayName: text("display_name").notNull(),
  defaultRestSeconds: integer("default_rest_seconds").notNull().default(90),
  ...timestamps,
});

export type Athlete = typeof athlete.$inferSelect;
export type NewAthlete = typeof athlete.$inferInsert;
